
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lrc_wpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lrc_wpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.198990216224132e+00, -4.116236545417817e+00, -4.000354984844966e+00, -3.839991812270999e+00, -3.621820909413278e+00, -3.332188936002519e+00, -2.960973941951694e+00, -2.508467735754214e+00, -1.994141466916513e+00, -1.457209181314120e+00, -9.308701365906324e-01, -5.872286791362953e-01, -4.935762199217320e-01, -3.780781334170824e-01, -2.333841911716135e-01, -1.038465504667591e-01, -2.319412031027584e-02, -6.528628394101275e-04, -4.800427472537987e-06, -6.623504158190123e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


